#include <bits/stdc++.h>
using namespace std;

struct Pos {
    int r, c;
    Pos(int _r = 0, int _c = 0) : r(_r), c(_c) {}
};

int N, T, W;
vector<string> B;
vector<int> D1, D2;
int dr[4] = {-1, 0, 0, 1};
int dc[4] = {0, -1, 1, 0};

inline int ID(int r, int c) { return r * W + c; }

void bfs_z(const Pos& src) {
    D1.assign(W * W, -1);
    queue<Pos> q;
    D1[ID(src.r, src.c)] = 0;
    q.push(src);
    while (!q.empty()) {
        Pos u = q.front();
        q.pop();
        int ui = ID(u.r, u.c);
        for (int k = 0; k < 4; ++k) {
            int nr = u.r + dr[k], nc = u.c + dc[k];
            if (B[nr][nc] != '.') continue;
            int ni = ID(nr, nc);
            if (D1[ni] != -1) continue;
            D1[ni] = D1[ui] + 1;
            q.push(Pos(nr, nc));
        }
    }
}

void bfs_one(const Pos& src) {
    D2.assign(W * W, -1);
    queue<Pos> q;
    D2[ID(src.r, src.c)] = 0;
    q.push(src);
    while (!q.empty()) {
        Pos u = q.front();
        q.pop();
        int ui = ID(u.r, u.c);
        if (D1[ui] >= 0 && D2[ui] >= D1[ui]) continue;
        for (int k = 0; k < 4; ++k) {
            int nr = u.r + dr[k], nc = u.c + dc[k];
            if (B[nr][nc] != '.') continue;
            int ni = ID(nr, nc);
            if (D2[ni] != -1) continue;
            if (D1[ni] >= 0 && D1[ni] < D2[ui] + 1) continue;
            D2[ni] = D2[ui] + 1;
            q.push(Pos(nr, nc));
        }
    }
}

struct Edge {
    int to, rev, cap;
};

vector<vector<Edge> > G;

void add_edge(int u, int v, int c) {
    Edge a = {v, (int)G[v].size(), c};
    Edge b = {u, (int)G[u].size(), 0};
    G[u].push_back(a);
    G[v].push_back(b);
}

int dinic(int s, int t) {
    const int INF = 1000000000;
    int ans = 0;
    while (true) {
        vector<int> level(G.size(), -1);
        queue<int> q;
        level[s] = 0;
        q.push(s);
        while (!q.empty()) {
            int v = q.front();
            q.pop();
            for (const Edge& e : G[v]) {
                if (e.cap > 0 && level[e.to] == -1) {
                    level[e.to] = level[v] + 1;
                    q.push(e.to);
                }
            }
        }
        if (level[t] == -1) break;

        vector<int> it(G.size(), 0);
        function<int(int,int)> dfs;
        dfs = [&](int v, int f) -> int {
            if (v == t) return f;
            for (int &i = it[v]; i < (int)G[v].size(); ++i) {
                Edge &e = G[v][i];
                if (e.cap > 0 && level[e.to] == level[v] + 1) {
                    int pushed = dfs(e.to, min(f, e.cap));
                    if (pushed > 0) {
                        e.cap -= pushed;
                        G[e.to][e.rev].cap += pushed;
                        return pushed;
                    }
                }
            }
            return 0;
        };
        int pushed;
        while ((pushed = dfs(s, INF)) > 0) ans += pushed;
    }
    return ans;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N >> T;
    W = N + 2;

    B.assign(W, string(W, '#'));
    string row;
    for (int r = 1; r <= N; ++r) {
        cin >> row;
        for (int c = 1; c <= N; ++c) B[r][c] = row[c - 1];
    }
    vector<string> B1 = B;

    vector<string> B2(W, string(W, '#'));
    for (int r = 1; r <= N; ++r) {
        cin >> row;
        for (int c = 1; c <= N; ++c) B2[r][c] = row[c - 1];
    }

    vector<Pos> sci, caps;
    Pos z;
    for (int r = 1; r <= N; ++r) {
        for (int c = 1; c <= N; ++c) {
            char ch = B[r][c];
            if (ch >= '0' && ch <= '9') {
                if (ch > '0') sci.push_back(Pos(r, c));
                B[r][c] = '.';
            } else if (ch == 'Z') {
                z = Pos(r, c);
                B[r][c] = '.';
            }
            char ch2 = B2[r][c];
            if (ch2 >= '0' && ch2 <= '9' && ch2 > '0')
                caps.push_back(Pos(r, c));
        }
    }

    bfs_z(z);

    int nS = (int)sci.size();
    int nC = (int)caps.size();
    int SRC = 0;
    int SINK = nS + nC + 1;
    int V = SINK + 1;
    G.assign(V, vector<Edge>());

    const int INF = 98765432;

    for (int i = 0; i < nS; ++i) {
        const Pos& s = sci[i];
        add_edge(SRC, i + 1, B1[s.r][s.c] - '0');
    }
    for (int j = 0; j < nC; ++j) {
        const Pos& c = caps[j];
        add_edge(nS + j + 1, SINK, B2[c.r][c.c] - '0');
    }

    for (int i = 0; i < nS; ++i) {
        const Pos& s = sci[i];
        bfs_one(s);
        for (int j = 0; j < nC; ++j) {
            const Pos& c = caps[j];
            int ci = ID(c.r, c.c);
            if (D2[ci] >= 0 && D2[ci] <= T)
                add_edge(i + 1, nS + j + 1, INF);
        }
    }

    cout << dinic(SRC, SINK) << '\n';
    return 0;
}
